/**
 * Join optimizer for LMDB stores that do not (yet) have sketch-based statistics.
 * <p>
 * It is {@link QueryJoinOptimizer} with one addition: the cost of a statement pattern is corrected for bound variables
 * that no configured LMDB index can seek on. Connectedness, bound-variable detection and everything else come from the
 * base optimizer.
 */
class LmdbIndexAwareJoinOptimizer extends QueryJoinOptimizer {

	private final EvaluationStatistics lmdbStatistics;

	LmdbIndexAwareJoinOptimizer(EvaluationStatistics statistics, boolean trackResultSize, TripleSource tripleSource,
			QueryExecutionPolicy policy) {
		super(statistics, trackResultSize, tripleSource, policy);
		this.lmdbStatistics = statistics;
	}

	@Override
	protected JoinVisitor createJoinVisitor() {
		return new IndexAwareJoinVisitor();
	}

	protected class IndexAwareJoinVisitor extends JoinVisitor {

		/**
		 * The base cost of a statement pattern is discounted for every variable that is already bound: it assumes a
		 * bound variable narrows the lookup. That only holds when an LMDB index can seek on the bound components. When
		 * a bound variable cannot be part of the seekable prefix of any index (for example a bound object when only
		 * {@code spoc} and {@code posc} exist), the scan still reads every row matching the shorter prefix and the
		 * variable merely filters.
		 * <p>
		 * With {@code k} the number of positions that are constants or bound variables, {@code p} the longest seekable
		 * prefix and {@code u = min(k - p, boundVarCount)} the bound variables that cannot be seeked on, this
		 * multiplies the base cost by {@code (cardinality + 5) ^ (u / nonConstantVarCount)}. That is exactly the factor
		 * the base formula took off for those {@code u} variables.
		 */
		@Override
		protected double getTupleExprCost(TupleExpr tupleExpr, Map<TupleExpr, Double> cardinalityMap,
				Map<TupleExpr, List<Var>> varsMap, Map<Var, Integer> varFreqMap) {
			double cost = super.getTupleExprCost(tupleExpr, cardinalityMap, varsMap, varFreqMap);
			if (!(tupleExpr instanceof StatementPattern pattern)
					|| !(lmdbStatistics instanceof LmdbEvaluationStatistics statistics)
					|| statistics.supportsJoinEstimation()) {
				return cost;
			}

			List<Var> vars = varsMap.get(pattern);
			if (vars == null) {
				return cost;
			}
			List<Var> unbound = getUnboundVars(vars);
			Set<String> boundNames = new HashSet<>();
			int nonConstantVarCount = 0;
			for (Var var : vars) {
				if (var == null || var.hasValue() || var.getName() == null) {
					continue;
				}
				nonConstantVarCount++;
				if (!unbound.contains(var)) {
					boundNames.add(var.getName());
				}
			}
			int boundVarCount = boundNames.size();
			if (boundVarCount == 0 || nonConstantVarCount == 0) {
				return cost;
			}

			int k = 0;
			for (Var position : new Var[] { pattern.getSubjectVar(), pattern.getPredicateVar(),
					pattern.getObjectVar(), pattern.getContextVar() }) {
				if (position != null && (position.hasValue()
						|| (position.getName() != null && boundNames.contains(position.getName())))) {
					k++;
				}
			}
			int p = statistics.fallbackAccessPrefixLength(pattern, boundNames);
			if (p >= k) {
				return cost;
			}

			int u = Math.min(k - p, boundVarCount);
			// same lookup as the base cost: the cached cardinality of the node wins over the map
			double cardinality = pattern.isCardinalitySet() ? pattern.getCardinality() : cardinalityMap.get(pattern);
			return cost * Math.pow(cardinality + 5, (double) u / nonConstantVarCount);
		}
	}
}
